internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Camera mainCamera = Camera.main;
        if (mainCamera == null)
        {
            result.Log("MainCamera.instanceID=NOT_FOUND");
        }
        else
        {
            result.Log("MainCamera.instanceID=" + mainCamera.gameObject.GetInstanceID());
        }
    }
}

